// Tests for dashboard/widgets/index.js (generated by tools/catalog.py) and the Dwidgets' meta.js.
// Run: node dashboard/widgets/tests/index.test.js
// The index is the one line a new widget folder adds: this checks it still matches the folders, on
// `main` too, where tools/ doesn't ship.
const fs = require("fs");
const path = require("path");
const assert = require("assert");

const { rootOf, make } = require("../../../base/core/tests/qmljs.js");
const root = rootOf(__dirname);
const { lib } = make(root);

const DIR = path.join(__dirname, "..");
const C = lib("dashboard/widgets/catalog.js", ["WIDGETS", "FOLDERS", "has", "style", "validStyle", "validSize", "parseSize", "renamed"]);

const folders = fs.readdirSync(DIR)
    .filter(n => fs.existsSync(path.join(DIR, n, "meta.js")))
    .sort();
const index = fs.readFileSync(path.join(DIR, "index.js"), "utf8");
const imported = [...index.matchAll(/^\.import "([^/]+)\/meta\.js" as (\w+)$/gm)].map(m => m[1]);

let passed = 0, failed = 0;
function test(name, fn) {
    try {
        fn();
        passed++;
    } catch (e) {
        failed++;
        console.log("FAIL " + name + "\n  " + e.message);
    }
}

test("the index imports exactly the folders that have a meta.js", () => {
    assert.deepStrictEqual(imported, folders);
});

test("every Dwidget's folder exists and draws it", () => {
    assert.deepStrictEqual(Object.keys(C.WIDGETS), Object.keys(C.FOLDERS));
    for (const id in C.FOLDERS) {
        const f = C.FOLDERS[id];
        assert.ok(folders.includes(f), id + ": unknown folder " + f);
        assert.ok(fs.existsSync(path.join(DIR, f, "Widget.qml")), f + ": no Widget.qml");
    }
});

test("every Dwidget describes itself", () => {
    for (const id in C.WIDGETS) {
        const w = C.WIDGETS[id];
        assert.ok(w.title, id + ": no title");
        assert.ok(w.icon, id + ": no icon");
        assert.ok(w.styles.length, id + ": no styles");
        for (const s of w.styles) {
            assert.ok(s.id && s.title, id + ": a style needs an id and a title");
            assert.ok(s.sizes.length, id + "/" + s.id + ": no sizes");
            for (const z of s.sizes)
                assert.ok(C.parseSize(z), id + "/" + s.id + ": bad size " + z);
        }
    }
});

test("every default and expand size is one the style allows", () => {
    for (const id in C.WIDGETS) {
        const d = C.WIDGETS[id].defaults;
        assert.ok(C.validStyle(id, d.idle.style), id + ": the default style is not one of its styles");
        assert.ok(C.validSize(id, d.idle.style, d.idle.size), id + ": the default size is not one of that style's");
        const x = C.WIDGETS[id].expand;
        if (x)
            assert.ok(C.parseSize(x.size), id + ": bad expand size " + x.size);
    }
});

test("every rename points at a style that exists", () => {
    for (const id in C.WIDGETS)
        for (const old in C.WIDGETS[id].renames || {})
            assert.ok(C.validStyle(id, C.renamed(id, old)),
                id + ": " + old + " renames to a style it doesn't have: " + C.renamed(id, old));
});

console.log(passed + " passed, " + failed + " failed");
process.exit(failed ? 1 : 0);
